1	/* ==========================================================
2	   Section  (Webflow: .section-regular-3.blue-sec.makeit-sec)
3	   Base .section-regular-3: padding: 0 5% 80px
4	   .blue-sec modifier:     background: #082753; margin-bottom: 0; padding-top: 70px; padding-bottom: 70px
5	   .makeit-sec override:   padding-bottom: 80px
6	   Combined result:        padding: 70px 5% 80px; background: #082753
7	   ========================================================== */
8	.sectionRegular3BlueSec {
9	  -webkit-text-fill-color: inherit;
10	  background-color: #082753;
11	  background-clip: border-box;
12	  margin-bottom: 0;
13	  padding: 70px 5% 80px;
14	  position: relative;
15	}
16	
17	/* ==========================================================
18	   Container  (Webflow: .container-large-3)
19	   ========================================================== */
20	.containerLarge3 {
21	  width: 100%;
22	  max-width: 1280px;
23	  margin-left: auto;
24	  margin-right: auto;
25	}
26	
27	/* ==========================================================
28	   Badge row  (Webflow: .how-work-tag-badge / .how-work-badge)
29	   ========================================================== */
30	.howWorkTagBadge {
31	  grid-column-gap: 10px;
32	  grid-row-gap: 10px;
33	  justify-content: center;
34	  align-items: center;
35	  display: flex;
36	}
37	
38	.howWorkBadge {
39	  background-color: #21cfff12;
40	  border: 1px solid #05bafe;
41	  border-radius: 20px;
42	  margin-bottom: 0;
43	  padding: 0 13px;
44	  line-height: 14px;
45	}
46	
47	/* ==========================================================
48	   Gradient text  (Webflow: .faq-sky-text)
49	   ========================================================== */
50	.faqSkyText {
51	  color: #21cfff;
52	  text-transform: capitalize;
53	  -webkit-text-fill-color: transparent;
54	  background-image: linear-gradient(90deg, #21cfff, #019ae6);
55	  -webkit-background-clip: text;
56	  background-clip: text;
57	  font-weight: 500;
58	}
59	
60	/* ==========================================================
61	   Heading  (Webflow: .heading-2.margin-bottom-24px.white-heading)
62	   Base .heading-2: color #082753, 40px/45px, text-align center, mb 20px
63	   .white-heading: color #fff
64	   Combined:
65	   ========================================================== */
66	.heading2WhiteHeading {
67	  color: #fff;
68	  font-family: Roobert PRO, Arial, sans-serif;
69	  font-size: 40px;
70	  text-align: center;
71	  line-height: 45px;
72	  margin-bottom: 20px;
73	}
74	
75	/* ==========================================================
76	   Subtitle  (Webflow: .paragraph.white.opacity)
77	   ========================================================== */
78	.paragraphWhiteOpacity {
79	  color: #fff;
80	  opacity: 0.8;
81	  font-size: 16px;
82	  line-height: 28px;
83	  text-align: center;
84	  margin-bottom: 0;
85	}
86	
87	/* ==========================================================
88	   Grid  (Webflow: .feature-grid.margin-top-40px)
89	   ========================================================== */
90	.featureGrid {
91	  display: grid;
92	  grid-column-gap: 20px;
93	  grid-row-gap: 20px;
94	  grid-template-rows: auto;
95	  grid-template-columns: 1fr 1fr 1fr;
96	  margin-top: 40px;
97	}
98	
99	/* ==========================================================
100	   Card  (Webflow: .feature-card.space-between.blue)
101	   Base .feature-card:               padding 25px 17px 17px; border-radius 20px; display flex; flex-flow column
102	   .space-between modifier:          justify-content: space-between; background #def4ff (overridden by .blue)
103	   .blue modifier:                   background #1c3861; border #ffffff1c
104	   ========================================================== */
105	.featureCardBlue {
106	  grid-column-gap: 0px;
107	  grid-row-gap: 0px;
108	  text-align: center;
109	  mix-blend-mode: normal;
110	  background-color: #1c3861;
111	  background-image: none;
112	  border: 1px solid rgba(255, 255, 255, 0.11);
113	  border-radius: 20px;
114	  flex-flow: column;
115	  justify-content: space-between;
116	  align-items: center;
117	  padding: 25px 17px 17px;
118	  text-decoration: none;
119	  display: flex;
120	}
121	
122	/* ==========================================================
123	   Text wrapper  (Webflow: .text-wrapper)
124	   No margin-bottom in Webflow base — space-between handles separation
125	   ========================================================== */
126	.textWrapper {
127	}
128	
129	/* ==========================================================
130	   Card title  (Webflow: .subheading-large.white)
131	   ========================================================== */
132	.subheadingLargeWhite {
133	  color: #fff;
134	  letter-spacing: -0.02em;
135	  margin-bottom: 10px;
136	  font-family: Roobert PRO, Arial, sans-serif;
137	  font-size: 20px;
138	  font-weight: 700;
139	  line-height: 25px;
140	}
141	
142	/* ==========================================================
143	   Card body  (Webflow: .paragraph-small-2.margin-bottom-20px.white.opacity)
144	   ========================================================== */
145	.paragraphSmall2WhiteOpacity {
146	  color: #fff;
147	  opacity: 0.8;
148	  min-height: auto;
149	  font-family: Roobert PRO, Arial, sans-serif;
150	  font-size: 16px;
151	  letter-spacing: -0.08px;
152	  margin-bottom: 20px;
153	  line-height: 28px;
154	}
155	
156	/* ==========================================================
157	   Card image  (Webflow: .full-width-image — plain, NO drop-shadow)
158	   Webflow line 13651: width: 100%; max-width: 3768px; display: block
159	   No height attribute on <img> in Webflow HTML → renders at natural ratio.
160	   ========================================================== */
161	.imageWrapper {
162	  position: relative;
163	  width: 100%;
164	  aspect-ratio: 1492 / 840;
165	  overflow: hidden;
166	}
167	
168	.fullWidthImage {
169	  object-fit: cover;
170	  object-position: top;
171	}
172	
173	/* ==========================================================
174	   @media (min-width: 1280px)
175	   Webflow line 21927: .feature-card.space-between → pl/pr 20px
176	   Webflow line 21944: .subheading-large → 25px/32px
177	   Webflow line 21932: .container-large-3 → max-width 1280px
178	   ========================================================== */
179	@media screen and (min-width: 1280px) {
180	  .featureCardBlue {
181	    padding-left: 20px;
182	    padding-right: 20px;
183	  }
184	
185	  .containerLarge3 {
186	    max-width: 1280px;
187	  }
188	
189	  .subheadingLargeWhite {
190	    font-size: 25px;
191	    line-height: 32px;
192	  }
193	}
194	
195	/* ==========================================================
196	   @media (min-width: 1440px)
197	   Webflow line 23367: .feature-card.space-between → pl/pr 25px
198	   Webflow line 23376: .container-large-3 → max-width 1320px
199	   ========================================================== */
200	@media screen and (min-width: 1440px) {
201	  .featureCardBlue {
202	    padding-left: 25px;
203	    padding-right: 25px;
204	  }
205	
206	  .containerLarge3 {
207	    max-width: 1320px;
208	  }
209	}
210	
211	/* ==========================================================
212	   @media (max-width: 991px)
213	   Webflow line 24574: .section-regular-3.blue-sec.makeit-sec → margin-top: 0
214	   Webflow line 24662: .blue-sec → padding-left: 2%; padding-right: 2%
215	     (the .blue-sec rule at 991px applies because the section element
216	      also has the .blue-sec class — Webflow cascades these separately)
217	   Webflow line 24562: .feature-grid.margin-top-40px → 3-col stays
218	   ========================================================== */
219	@media screen and (max-width: 991px) {
220	  .sectionRegular3BlueSec {
221	    margin-top: 0;
222	    /* .blue-sec rule at 991px: padding-left/right override to 2% */
223	    padding-left: 2%;
224	    padding-right: 2%;
225	  }
226	
227	  .heading2WhiteHeading {
228	    font-size: 35px;
229	    line-height: 45px;
230	  }
231	
232	  .featureGrid {
233	    /* stays 3-col per Webflow line 24562 for margin-top-40px variant */
234	    grid-template-columns: 1fr 1fr 1fr;
235	  }
236	}
237	
238	/* ==========================================================
239	   @media (max-width: 767px)
240	   Webflow line 27060: .section-regular-3 → padding-top: 0; padding-bottom: 0
241	   (overrides the base padding at mobile — the 479px rule restores for makeit-sec)
242	   feature-grid → 1 col
243	   ========================================================== */
244	@media screen and (max-width: 767px) {
245	  .sectionRegular3BlueSec {
246	    padding-top: 0;
247	    padding-bottom: 0;
248	    padding-left: 5%;
249	    padding-right: 5%;
250	    margin-top: 0;
251	  }
252	
253	  .featureGrid {
254	    grid-template-columns: 1fr;
255	    margin-top: 20px;
256	  }
257	
258	  .featureCardBlue {
259	    grid-column-gap: 0px;
260	    grid-row-gap: 0px;
261	    padding-left: 18px;
262	    padding-right: 18px;
263	  }
264	
265	  .subheadingLargeWhite {
266	    text-align: center;
267	  }
268	
269	  .paragraphSmall2WhiteOpacity {
270	    text-align: center;
271	  }
272	
273	  .heading2WhiteHeading {
274	    font-size: 23px;
275	    line-height: 32px;
276	    margin-bottom: 10px;
277	    text-align: center;
278	  }
279	
280	  .paragraphWhiteOpacity {
281	    text-align: center;
282	  }
283	
284	}
285	
286	/* ==========================================================
287	   @media (max-width: 479px)
288	   Webflow line 29623: .section-regular-3.blue-sec.makeit-sec →
289	     margin-top: 0; padding: 50px 5% 60px
290	   (restores padding that was zeroed at 767px for .section-regular-3 base)
291	   ========================================================== */
292	@media screen and (max-width: 479px) {
293	  .sectionRegular3BlueSec {
294	    margin-top: 0;
295	    padding: 50px 5% 60px;
296	  }
297	
298	  .featureGrid {
299	    grid-template-columns: 1fr;
300	  }
301	}
